import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { Star } from "@remotion/shapes";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TrustReviewsProps = Record<string, any>;

// Custom Star with Shadow Detail (Trustpilot Style)
const TrustPilotLogoStar: React.FC<{
  outerRadius: number;
  innerRadius: number;
  fill: string;
  style?: React.CSSProperties;
}> = ({ outerRadius, innerRadius, fill, style }) => {
  const size = outerRadius * 2;
  const cx = outerRadius;
  const cy = outerRadius;

  // Helper to get coordinates for a specific angle
  const getPoint = (radius: number, angleDeg: number) => {
    const angleRad = (angleDeg * Math.PI) / 180;
    return {
      x: cx + radius * Math.cos(angleRad),
      y: cy + radius * Math.sin(angleRad),
    };
  };

  // Standard 5-point star angles (Top is -90 degrees)
  // Outer points: -90, -18, 54, 126, 198
  // Inner points: -54, 18, 90, 162, 234
  const points = [
    getPoint(outerRadius, -90),  // Top
    getPoint(innerRadius, -54),
    getPoint(outerRadius, -18),  // Right Upper
    getPoint(innerRadius, 18),
    getPoint(outerRadius, 54),   // Right Lower
    getPoint(innerRadius, 90),   // Bottom Cleft
    getPoint(outerRadius, 126),  // Left Lower
    getPoint(innerRadius, 162),
    getPoint(outerRadius, 198),  // Left Upper
    getPoint(innerRadius, 234),
  ];

  const starPath = points.map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`)).join(" ") + " Z";

  // The shadow detail is a triangle formed by the Center, the Bottom Cleft (90deg), and the Right Lower Tip (54deg)
  // This creates the darker fold on the bottom-right leg.
  const pBottomCleft = getPoint(innerRadius, 90);
  const pRightLower = getPoint(outerRadius, 54);
  const shadowPath = `M ${cx} ${cy} L ${pBottomCleft.x} ${pBottomCleft.y} L ${pRightLower.x} ${pRightLower.y} Z`;

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={style}>
      <path d={starPath} fill={fill} />
      <path d={shadowPath} fill="rgba(0,0,0,0.2)" />
    </svg>
  );
};

const TrustReviews: React.FC<TrustReviewsProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  rating = 5,
  headerText = "Trustpilot",
  accentColor = "#00b67a",
  cardBackgroundColor = "#000000",
  textColor = "#ffffff",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Logic
  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Dimensions
  const cardWidth = Math.min(width * 0.8, 600);
  const cardHeight = cardWidth * 0.6; // Maintain aspect ratio roughly
  const borderRadius = cardWidth * 0.05;
  const padding = cardWidth * 0.08;

  // Animation Utilities
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const contentOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  const starRotation = interpolate(frame, [10, 60], [-180, 0], {
    extrapolateRight: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3), // cubic ease out
  });

  // Staggered box animation
  const getBoxSpring = (index: number) => {
    return spring({
      frame: frame - 20 - (index * 4), // Stagger by 4 frames
      fps,
      config: { damping: 15, stiffness: 120 },
    });
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: actualBgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Main Card */}
      <div
        style={{
          width: cardWidth,
          padding: padding,
          backgroundColor: cardBackgroundColor,
          borderRadius: borderRadius,
          border: `2px solid #ffffff`,
          display: "flex",
          flexDirection: "column",
          gap: padding * 0.5,
          transform: `scale(${entranceSpring})`,
          opacity: contentOpacity,
          boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
        }}
      >
        {/* Header Section: Star Logo + Text */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: padding * 0.4,
            width: "100%",
          }}
        >
          {/* Logo Star */}
          <div style={{ transform: `rotate(${starRotation}deg)` }}>
            <TrustPilotLogoStar
              innerRadius={cardWidth * 0.05}
              outerRadius={cardWidth * 0.11}
              fill="#00b67a" // Hardcoded logo color to stay green regardless of accentColor
              style={{
                filter: "drop-shadow(2px 4px 6px rgba(0,0,0,0.3))",
              }}
            />
          </div>

          {/* Title Text */}
          <h1
            style={{
              color: textColor,
              fontSize: cardWidth * 0.12,
              margin: 0,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              lineHeight: 1,
            }}
          >
            {headerText}
          </h1>
        </div>

        {/* Rating Boxes Section */}
        <div
          style={{
            display: "flex",
            width: "100%",
            gap: padding * 0.2,
            marginTop: padding * 0.2,
          }}
        >
          {Array.from({ length: 5 }).map((_, i) => {
            const isActive = i < rating;
            const boxScale = getBoxSpring(i);
            
            // If inactive, show grey box
            // If active, use accentColor (decoupled from logo)
            const boxColor = isActive ? accentColor : "#2a2a2a";

            return (
              <div
                key={i}
                style={{
                  flex: 1,
                  aspectRatio: "1/1",
                  backgroundColor: boxColor,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${boxScale})`,
                }}
              >
                <Star
                  points={5}
                  innerRadius={cardWidth * 0.04}
                  outerRadius={cardWidth * 0.085}
                  fill={isActive ? "#ffffff" : "#4a4a4a"} 
                />
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TrustReviews;